import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { createServer } from 'node:http';
import { join } from 'node:path';
import { loadConfig } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/config.js';
import { parseCustomProviders } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/custom-providers.js';
import { LegacyMikroBackend } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/mcp/backends/legacy.js';
import { runTurn, sessionResult } from './history-only-reword-6qjyzwas/tree/mikro/dist/src/mcp/server.js';
const parent = '/home/genie/.local/share/mikro-engine-split/experiments-g8/final-local-smokes';
async function run(childError) {
  const root = await mkdtemp(join(parent, 'child-empty-terminal-'));
  let requests = 0;
  const server = createServer(async (request, response) => {
    for await (const _chunk of request) {}
    const index = requests++;
    if (index > 4) { response.writeHead(400); response.end('unexpected extra request'); return; }
    if (index === 1 && childError) {
      response.writeHead(400, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ error: { message: 'local child rejected; no usage packet' } }));
      return;
    }
    const content = index === 0 ? '```repl\nchild = llm_query("local child prompt")\n```' : index === 1 ? 'known child answer' : '';
    response.writeHead(200, { 'Content-Type': 'text/event-stream' });
    response.end(`data: ${JSON.stringify({ id: `child-empty-${index}`, object: 'chat.completion.chunk', model: 'control', choices: [{ index: 0, delta: { role: 'assistant', content }, finish_reason: 'stop' }], usage: { prompt_tokens: 11, completion_tokens: index < 2 ? 7 : 0, total_tokens: index < 2 ? 18 : 11 } })}\n\ndata: [DONE]\n\n`);
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  process.env.CHILD_EMPTY_TERMINAL_KEY = 'local-fixture-only';
  try {
    const base = await loadConfig(root);
    const config = { ...base, system: null, criteria: null, tools: [], toolsLevel: 'core', validate: null, output: { schema: null }, budget: { maxCost: null, maxTokens: null, maxDepth: 0 }, cache: { ...base.cache, enabled: false }, storage: { ...base.storage, enabled: 'never' }, gemini: { ...base.gemini, thinkingLevel: null }, model: { provider: 'child-empty-fixture', model: 'control', providers: parseCustomProviders({ 'child-empty-fixture': { 'base-url': `http://127.0.0.1:${server.address().port}/v1`, 'api-key-env': 'CHILD_EMPTY_TERMINAL_KEY', models: { control: { cost: { input: 1, output: 2 } } } } }, 'local terminal coverage fixture') } };
    const outcome = await runTurn(new LegacyMikroBackend(), undefined, config, 'child-empty-fixture', 'Run the bounded child experiment', 'sess_child_empty', undefined, root, undefined, 5);
    const mcp = sessionResult(outcome.text, 'sess_child_empty', outcome.failed);
    const observedLine = outcome.text.split('\n').find((line) => line.startsWith('observed_usage: '));
    return { childError, requests, outcome, isError: mcp.isError === true, structuredContent: mcp.structuredContent, observedUsage: observedLine ? JSON.parse(observedLine.slice('observed_usage: '.length)) : null };
  } finally {
    delete process.env.CHILD_EMPTY_TERMINAL_KEY;
    server.closeAllConnections();
    await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
    await rm(root, { recursive: true, force: true });
  }
}
const completeControl = await run(false);
const unknownChildReceipt = await run(true);
console.log(JSON.stringify({ completeControl, unknownChildReceipt, externalModelCalls: 0, localProviderRequests: completeControl.requests + unknownChildReceipt.requests, jevCalls: 0 }));
for (const result of [completeControl, unknownChildReceipt]) {
  assert.equal(result.requests, 5, 'one child and four root calls, no outside-cap forced completion');
  assert.equal(result.isError, true, 'three empty replies remain a truthful terminal failure');
  assert.match(result.outcome.answer, /3 consecutive empty LLM responses/);
}
assert.equal(completeControl.observedUsage, null, 'complete observed control may keep the existing numeric footer');
assert.equal(unknownChildReceipt.observedUsage?.subtotal.inputTokens, 44, 'retain each known root input receipt once');
assert.equal(unknownChildReceipt.observedUsage?.subtotal.outputTokens, 7, 'retain known root output; genuinely empty calls reported zero output');
assert.ok(Math.abs((unknownChildReceipt.observedUsage?.subtotal.totalCost ?? NaN) - 0.000058) < 1e-12, 'known subtotal is not a complete bill');
assert.equal(unknownChildReceipt.observedUsage?.coverage, 'partial', 'missing child usage must survive the three-empty-response terminal return');
assert.equal(unknownChildReceipt.observedUsage?.totals, null, 'unreported child totals stay unknown');

